    46→
    47→  public DataColumnSidecarsByRangeListenerValidatingProxy(
    48→      final Spec spec,
    49→      final Peer peer,
    50→      final RpcResponseListener<DataColumnSidecar> dataColumnSidecarResponseListener,
    51→      final KZG kzg,
    52→      final MetricsSystem metricsSystem,
