    89→            throw new DataColumnSidecarsResponseInvalidResponseException(
    90→                peer,
    91→                DataColumnSidecarsResponseInvalidResponseException.InvalidResponseType
    92→                    .DATA_COLUMN_SIDECAR_INCLUSION_PROOF_VERIFICATION_FAILED);
    93→          }
    94→          try (MetricsHistogram.Timer ignored =
