                              KZGCellWithColumnId.fromCellAndColumn(
                                  new KZGCell(
                                      dataColumnSidecar.getDataColumn().get(rowIndex).getBytes()),
                                  dataColumnSidecar.getIndex().intValue())))
          .toList();

