    80→            "Total number of data column sidecars by range requests received",
    81→            "status");
    82→    totalDataColumnSidecarsRequestedCounter =
    83→        metricsSystem.createCounter(
    84→            TekuMetricCategory.NETWORK,
    85→            "rpc_data_column_sidecars_by_range_requested_sidecars_total",
    86→            "Total number of data column sidecars requested in accepted blob sidecars by range requests from peers");
    87→    this.dasLogger = dasLogger;
    88→  }
    89→
    90→  @Override
    91→  public Optional<RpcException> validateRequest(
    92→      final String protocolId, final DataColumnSidecarsByRangeRequestMessage request) {
    93→    final int maxRequestDataColumnSidecars = specConfigFulu.getMaxRequestDataColumnSidecars();
    94→    final int requestedCount = calculateRequestedCount(request);
    95→
    96→    if (requestedCount == -1 || requestedCount > maxRequestDataColumnSidecars) {
    97→      requestCounter.labels("count_too_big").inc();
