   141→
   142→    UInt64 finalizedSlot = combinedChainDataClient.getFinalizedBlockSlot().orElse(UInt64.ZERO);
   143→
   144→    final SortedMap<UInt64, Bytes32> canonicalHotRoots;
   145→    if (endSlot.isGreaterThan(finalizedSlot)) {
   146→      canonicalHotRoots =
   147→          combinedChainDataClient.getAncestorRoots(startSlot, UInt64.ONE, message.getCount());
   148→
   149→      // refresh finalized slot to avoid race condition that can occur if we finalize just
   150→      // before getting hot canonical roots
   151→      finalizedSlot = combinedChainDataClient.getFinalizedBlockSlot().orElse(UInt64.ZERO);
   152→    } else {
   153→      canonicalHotRoots = ImmutableSortedMap.of();
   154→    }
   155→
   156→    final RequestState initialState =
