   158→            responseCallbackWithLogging,
   159→            specConfigFulu.getMaxRequestDataColumnSidecars(),
   160→            startSlot,
   161→            endSlot,
   162→            columns,
   163→            canonicalHotRoots,
   164→            finalizedSlot);
