   174→        requestState -> {
   175→          final int sentDataColumnSidecars = requestState.sentDataColumnSidecars.get();
   176→          if (sentDataColumnSidecars != requestedCount) {
   177→            peer.adjustDataColumnSidecarsRequest(maybeRequestKey.get(), sentDataColumnSidecars);
   178→          }
   179→          responseCallbackWithLogging.completeSuccessfully();
   180→        },
